import * as s from "../../core/validation/index.js";
import type { Schema } from "../../core/validation/schema.js";

/**
 * Accepts a JSON object that maps tokens to an associated bias value. Mathematically, the bias is
 * added to the logits generated by the model prior to sampling. The exact effect will vary per
 * model.
 */
export type LogitBias = Record<string, unknown>;

export const logitBiasSchema: Schema<LogitBias> = s.of<LogitBias>(
  s.union([s.record(s.string(), s.unknown())]),
);
